package com.example.madfinalproject;
import android.content.Intent; import android.os.Bundle; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity;
public class PteLessonsActivity extends AppCompatActivity {protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_ielts_lessons);PteUiAdapter.apply(findViewById(android.R.id.content));((TextView)findViewById(R.id.tabLessons)).setTextColor(PteUiAdapter.TEAL);wire();}private void wire(){findViewById(R.id.btnBack).setOnClickListener(v->finish());findViewById(R.id.tabOverview).setOnClickListener(v->open(PtePreparationActivity.class));findViewById(R.id.tabPractice).setOnClickListener(v->open(PtePracticeActivity.class));findViewById(R.id.tabMockTests).setOnClickListener(v->open(PteMockTestsActivity.class));findViewById(R.id.tabReports).setOnClickListener(v->open(PteReportsActivity.class));}private void open(Class<?> c){startActivity(new Intent(this,c));finish();}}
